<?php require_once __DIR__.'/../includes/auth.php';require_login();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$a=$id?query_one('SELECT qa.*,q.title_en,q.title_si,q.title_ta,q.pass_mark FROM quiz_attempts qa JOIN quizzes q ON q.id=qa.quiz_id WHERE qa.id=? AND qa.user_id=?','ii',[$id,user()['id']]):null;if(!$a)redirect('student/progress.php');$s=db()->prepare('SELECT qq.*,ans.selected_option,ans.is_correct FROM quiz_answers ans JOIN quiz_questions qq ON qq.id=ans.question_id WHERE ans.attempt_id=? ORDER BY qq.display_order,qq.id');$s->bind_param('i',$id);$s->execute();$pageTitle=tr('results');include __DIR__.'/../includes/header.php';?><section class="card"><h1><?=e(locale_value($a,'title'))?></h1><div style="font-size:3rem;font-weight:900"><?=intval($a['percentage'])?>%</div><p><?=intval($a['score'])?> / <?=intval($a['total_questions'])?> · <?=$a['passed']?'Passed 🎉':'Keep practising 💪'?></p><a class="btn" href="quiz.php?id=<?=$a['quiz_id']?>">Retry quiz</a></section><?php if(is_premium()):while($x=$s->get_result()->fetch_assoc()):?><section class="card"><h3><?=e(locale_value($x,'question'))?></h3><p><?=$x['is_correct']?'✅':'❌'?> Your answer: <?=e(strtoupper((string)$x['selected_option']))?> · Correct: <?=e(strtoupper($x['correct_option']))?></p><p><?=e(locale_value($x,'explanation'))?></p></section><?php endwhile;else:?><section class="card locked" style="text-align:center;padding:30px"><div style="font-size:2.5rem">🔒</div><span class="badge">Premium feature</span><h2>Unlock the complete answer review</h2><p class="muted">See every correct answer and explanation for Rs. 250 per 30 days.</p><a class="btn warn" href="<?=url('subscription.php')?>">View Premium · Rs. 250 →</a></section><?php endif;include __DIR__.'/../includes/footer.php';?>
